-- Repeatable for this bundled catalogue; run once at a time.
begin;
set local standard_conforming_strings = on;
commit;
select 'patterns' as table_name, count(*) as rows from public.patterns union all select 'problems',count(*) from public.problems union all select 'bank_mcqs',count(*) from public.mcqs where source='bank';
