insert into public.mcqs (problem_id,question,options,correct_index,explanation,source) select p.id,'For **Pair with Target Sum (easy)**, what makes moving one pointer at a time useful?','["It lets each comparison eliminate positions that cannot satisfy the condition", "It guarantees every pair is checked", "It sorts the input automatically", "It makes the algorithm independent of input size"]'::jsonb,0,'A pointer move is justified by the ordering or constraint: it discards candidates that cannot work, avoiding a nested scan.','bank' from public.problems p where p.title='Pair with Target Sum (easy)' and not exists (select 1 from public.mcqs m where m.problem_id=p.id and m.source='bank' and m.question='For **Pair with Target Sum (easy)**, what makes moving one pointer at a time useful?');
insert into public.mcqs (problem_id,question,options,correct_index,explanation,source) select p.id,'When is the two-pointer strategy especially effective for **Pair with Target Sum (easy)**?','["When every element must be compared with every other element", "When useful positions can be scanned from two ends or maintained as a pair", "Only when the input is a tree", "Only when extra space must be O(n)"]'::jsonb,1,'Two pointers are effective when the problem structure lets pointer movement rule out candidates safely.','bank' from public.problems p where p.title='Pair with Target Sum (easy)' and not exists (select 1 from public.mcqs m where m.problem_id=p.id and m.source='bank' and m.question='When is the two-pointer strategy especially effective for **Pair with Target Sum (easy)**?');
insert into public.mcqs (problem_id,question,options,correct_index,explanation,source) select p.id,'What is the main reason a sorted input can help a two-pointer solution to **Pair with Target Sum (easy)**?','["Sorting makes all values equal", "Sorting removes duplicate values", "The order tells us which pointer to move after comparing the current values", "Sorting guarantees constant-time access to every pair"]'::jsonb,2,'Sorted order gives directional information, so a comparison can indicate which pointer movement may improve the result.','bank' from public.problems p where p.title='Pair with Target Sum (easy)' and not exists (select 1 from public.mcqs m where m.problem_id=p.id and m.source='bank' and m.question='What is the main reason a sorted input can help a two-pointer solution to **Pair with Target Sum (easy)**?');
insert into public.mcqs (problem_id,question,options,correct_index,explanation,source) select p.id,'What is a common complexity benefit of a linear two-pointer scan in **Pair with Target Sum (easy)**?','["It always uses O(n²) time", "It requires recursion for every element", "It checks all possible subarrays", "It can often process n elements in O(n) time"]'::jsonb,3,'Each pointer advances only a bounded number of times, so the scan is linear rather than checking all pairs.','bank' from public.problems p where p.title='Pair with Target Sum (easy)' and not exists (select 1 from public.mcqs m where m.problem_id=p.id and m.source='bank' and m.question='What is a common complexity benefit of a linear two-pointer scan in **Pair with Target Sum (easy)**?');
insert into public.mcqs (problem_id,question,options,correct_index,explanation,source) select p.id,'What should you verify before moving a pointer in **Pair with Target Sum (easy)**?','["That the move cannot discard a valid answer", "That the pointer moves by exactly two positions", "That the array contains no negative values", "That a hash map is empty"]'::jsonb,0,'The correctness of two pointers depends on a proof that the movement safely eliminates impossible candidates.','bank' from public.problems p where p.title='Pair with Target Sum (easy)' and not exists (select 1 from public.mcqs m where m.problem_id=p.id and m.source='bank' and m.question='What should you verify before moving a pointer in **Pair with Target Sum (easy)**?');
