insert into public.mcqs (problem_id,question,options,correct_index,explanation,source) select p.id,'Why does a stack fit **remove adjacent duplicates**?','["It keeps the oldest item at the top", "The most recently added unresolved item may need to be processed first", "It automatically sorts values", "It provides random access in O(1)"]'::jsonb,1,'LIFO order is useful when the latest unmatched or unresolved item must be handled before earlier ones.','bank' from public.problems p where p.title='remove adjacent duplicates' and not exists (select 1 from public.mcqs m where m.problem_id=p.id and m.source='bank' and m.question='Why does a stack fit **remove adjacent duplicates**?');
