insert into public.mcqs (problem_id,question,options,correct_index,explanation,source) select p.id,'Why does binary search reduce the search range after checking the middle?','["Because the midpoint is always the answer", "Because it randomly samples candidates", "Because ordering or monotonicity proves one side cannot contain a valid answer", "Because it sorts the data after each step"]'::jsonb,2,'The key correctness argument is that the discarded half is impossible under the problem’s ordering property.','bank' from public.problems p where p.title='Upper Bound/ Ceiling' and not exists (select 1 from public.mcqs m where m.problem_id=p.id and m.source='bank' and m.question='Why does binary search reduce the search range after checking the middle?');
insert into public.mcqs (problem_id,question,options,correct_index,explanation,source) select p.id,'What is the typical time complexity of binary search on n ordered elements?','["O(n)", "O(n²)", "O(1)", "O(log n)"]'::jsonb,3,'Each iteration roughly halves the remaining search interval, giving logarithmic iterations.','bank' from public.problems p where p.title='Upper Bound/ Ceiling' and not exists (select 1 from public.mcqs m where m.problem_id=p.id and m.source='bank' and m.question='What is the typical time complexity of binary search on n ordered elements?');
