insert into public.mcqs (problem_id,question,options,correct_index,explanation,source) select p.id,'What is the typical time complexity of binary search on n ordered elements?','["O(n)", "O(n²)", "O(1)", "O(log n)"]'::jsonb,3,'Each iteration roughly halves the remaining search interval, giving logarithmic iterations.','bank' from public.problems p where p.title='Search 2 D matrix' and not exists (select 1 from public.mcqs m where m.problem_id=p.id and m.source='bank' and m.question='What is the typical time complexity of binary search on n ordered elements?');
