insert into public.mcqs (problem_id,question,options,correct_index,explanation,source) select p.id,'Why is a heap useful for **kth smallest**?','["It maintains quick access to the smallest or largest priority element", "It stores all values in fully sorted order", "It supports constant-time search for any arbitrary value", "It removes duplicates automatically"]'::jsonb,0,'A heap maintains a partial order that makes the root the highest-priority item, enabling efficient repeated selection.','bank' from public.problems p where p.title='kth smallest' and not exists (select 1 from public.mcqs m where m.problem_id=p.id and m.source='bank' and m.question='Why is a heap useful for **kth smallest**?');
