insert into public.mcqs (problem_id,question,options,correct_index,explanation,source) select p.id,'Why choose a min-heap or max-heap carefully in **kth smallest**?','["The two heaps are always identical", "Heap type affects only memory", "The root must represent the candidate that should be selected or discarded next", "A heap cannot contain repeated values"]'::jsonb,2,'The root is the next priority item, so the heap orientation must match the algorithm’s selection rule.','bank' from public.problems p where p.title='kth smallest' and not exists (select 1 from public.mcqs m where m.problem_id=p.id and m.source='bank' and m.question='Why choose a min-heap or max-heap carefully in **kth smallest**?');
