insert into public.mcqs (problem_id,question,options,correct_index,explanation,source) select p.id,'Why is a heap useful for **K closest points to origin**?','["It maintains quick access to the smallest or largest priority element", "It stores all values in fully sorted order", "It supports constant-time search for any arbitrary value", "It removes duplicates automatically"]'::jsonb,0,'A heap maintains a partial order that makes the root the highest-priority item, enabling efficient repeated selection.','bank' from public.problems p where p.title='K closest points to origin' and not exists (select 1 from public.mcqs m where m.problem_id=p.id and m.source='bank' and m.question='Why is a heap useful for **K closest points to origin**?');
insert into public.mcqs (problem_id,question,options,correct_index,explanation,source) select p.id,'What is the typical cost of inserting or removing one item from a binary heap of size n?','["O(1)", "O(log n)", "O(n²)", "O(2ⁿ)"]'::jsonb,1,'The item may move along the heap height, which is logarithmic for a binary heap.','bank' from public.problems p where p.title='K closest points to origin' and not exists (select 1 from public.mcqs m where m.problem_id=p.id and m.source='bank' and m.question='What is the typical cost of inserting or removing one item from a binary heap of size n?');
