insert into public.mcqs (problem_id,question,options,correct_index,explanation,source) select p.id,'What is essential for a correct recursive solution to **Fibonnaci**?','["A base case that stops recursion and a step that makes progress toward it", "A global variable for every function", "A sorted input", "A hash map in every call"]'::jsonb,0,'The base case prevents infinite recursion, while each recursive call must move toward a smaller or simpler subproblem.','bank' from public.problems p where p.title='Fibonnaci' and not exists (select 1 from public.mcqs m where m.problem_id=p.id and m.source='bank' and m.question='What is essential for a correct recursive solution to **Fibonnaci**?');
insert into public.mcqs (problem_id,question,options,correct_index,explanation,source) select p.id,'What distinguishes backtracking from plain recursion in many problems?','["It never branches", "It explores a choice, then undoes that choice before trying another", "It uses no call stack", "It always finds the shortest path"]'::jsonb,1,'Backtracking systematically explores alternatives and restores state so sibling choices start from the correct state.','bank' from public.problems p where p.title='Fibonnaci' and not exists (select 1 from public.mcqs m where m.problem_id=p.id and m.source='bank' and m.question='What distinguishes backtracking from plain recursion in many problems?');
insert into public.mcqs (problem_id,question,options,correct_index,explanation,source) select p.id,'Why can backtracking have exponential time complexity?','["It always sorts the input", "It uses two pointers", "The number of candidate choices can branch across multiple levels", "It stores only one variable"]'::jsonb,2,'When many choices are explored at each level, the search tree can contain exponentially many states.','bank' from public.problems p where p.title='Fibonnaci' and not exists (select 1 from public.mcqs m where m.problem_id=p.id and m.source='bank' and m.question='Why can backtracking have exponential time complexity?');
insert into public.mcqs (problem_id,question,options,correct_index,explanation,source) select p.id,'What is the role of pruning in **Fibonnaci**?','["To skip the base case", "To increase recursion depth", "To revisit completed branches", "To stop exploring a partial candidate that cannot lead to a valid solution"]'::jsonb,3,'Pruning reduces search by rejecting branches that are already impossible or cannot improve the result.','bank' from public.problems p where p.title='Fibonnaci' and not exists (select 1 from public.mcqs m where m.problem_id=p.id and m.source='bank' and m.question='What is the role of pruning in **Fibonnaci**?');
insert into public.mcqs (problem_id,question,options,correct_index,explanation,source) select p.id,'What bug can occur if a chosen element is not removed during backtracking?','["State from one branch leaks into another branch", "The input becomes sorted", "The base case runs first", "The recursion becomes iterative"]'::jsonb,0,'Undoing a choice restores the shared path/state before exploring the next alternative.','bank' from public.problems p where p.title='Fibonnaci' and not exists (select 1 from public.mcqs m where m.problem_id=p.id and m.source='bank' and m.question='What bug can occur if a chosen element is not removed during backtracking?');
