insert into public.mcqs (problem_id,question,options,correct_index,explanation,source) select p.id,'For **Sorted Array to BST**, why are traversal sequences useful for reconstructing a tree?','["They encode root and subtree ordering information", "They always contain the same values in sorted order", "They specify every pointer directly", "They eliminate the need for recursion"]'::jsonb,0,'A traversal such as preorder or postorder identifies a root, while inorder can divide left and right subtrees when values are unique.','bank' from public.problems p where p.title='Sorted Array to BST' and not exists (select 1 from public.mcqs m where m.problem_id=p.id and m.source='bank' and m.question='For **Sorted Array to BST**, why are traversal sequences useful for reconstructing a tree?');
