insert into public.mcqs (problem_id,question,options,correct_index,explanation,source) select p.id,'When is BFS especially suitable among unweighted shortest-path problems?','["When edge weights are all negative", "When only a spanning tree is required", "When the graph is necessarily a DAG", "When minimum number of edges from a source is required"]'::jsonb,3,'BFS explores vertices level by level, so the first discovery gives a path with the fewest edges in an unweighted graph.','bank' from public.problems p where p.title='Cycle detection in directed graph' and not exists (select 1 from public.mcqs m where m.problem_id=p.id and m.source='bank' and m.question='When is BFS especially suitable among unweighted shortest-path problems?');
