insert into public.mcqs (problem_id,question,options,correct_index,explanation,source) select p.id,'What must change when selecting Dijkstra for **Cycle detection in directed graph**?','["It must use a stack only", "The edge-weight assumptions must be satisfied; standard Dijkstra requires non-negative weights", "The graph must be disconnected", "Every vertex must have degree two"]'::jsonb,1,'Dijkstra’s greedy finalization is valid for non-negative edge weights; negative weights require another method.','bank' from public.problems p where p.title='Cycle detection in directed graph' and not exists (select 1 from public.mcqs m where m.problem_id=p.id and m.source='bank' and m.question='What must change when selecting Dijkstra for **Cycle detection in directed graph**?');
